namespace DpiShell.App;

/// <summary>
/// Тексты кнопок «(i)» — дословно из docs/info-texts.md (обратные кавычки разметки убраны, абзацы — через пустую строку \n\n;
/// первый абзац — ответ «когда включать», в карточке он жирный). Ключ — заголовок раздела в документе.
/// Здесь и только здесь: в XAML — лишь ключ (InfoButton.Topic). Тест окна сверяет тексты с документом.
/// </summary>
public static class InfoTexts
{
    public const string Home = "Главная — включение и стратегия";
    public const string Select = "Подбор — быстрый / полный / глубокий";
    public const string Targets = "Свои адреса";
    public const string DomainLists = "Списки доменов";
    public const string IpLists = "IP-списки";
    public const string Game = "Игровой режим";
    public const string Hosts = "hosts — «Починить адреса»";
    public const string Dns = "DNS";
    public const string Diag = "Диагностика";
    public const string RouterMode = "Роутер — для каких сайтов обход";
    public const string SiteCheck = "Сайт не открывается";
    public const string RouterDns = "DNS для всей сети";
    public const string RouterWatchdog = "Сторож на роутере";

    public static readonly IReadOnlyDictionary<string, string> All = new Dictionary<string, string>
    {
        [Home] = "Нажмите «Включить» — стратегию программа подберёт сама; менять её стоит, только если сайты перестали открываться.\n\nЗдесь включается обход блокировок для этого компьютера. «Включить» запускает обход; если стратегия ещё не выбрана, программа сначала подберёт её сама — это 2–3 минуты. С настройкой «Обход работает, даже когда программа закрыта» обход работает и без окна, и после перезагрузки; без неё — пока программа открыта (в окне или в трее). Стратегия — это способ, которым обход обманывает оборудование провайдера; у разных провайдеров работают разные. Менять её вручную стоит, только если сайты перестали открываться. При смене стратегии обход перезапускается — открытые соединения на секунду прервутся.",
        [Select] = "Запускайте, если сайты перестали открываться: «Полный» надёжнее, «Быстрый» — быстрее.\n\nПодбор перебирает стратегии и проверяет, открываются ли YouTube, Discord и ваши адреса. «Быстрый» останавливается на первой, у которой всё открылось, — обычно 1–3 минуты. «Полный» проверяет все и выбирает самую надёжную. Если готовые не помогли, в итоге подбора появится «Искать глубже» — программа придумает новые стратегии, до 15 минут. Во время подбора обход несколько раз включается и выключается — сайты и игры будут прерываться. Лучшую стратегию подбор включает сам; другую можно выбрать в таблице и нажать «Применить выбранную».",
        [Targets] = "Добавляйте сайт, если он не открывается, а YouTube и Discord работают.\n\nСюда добавляют сайты, которые должны открываться, кроме YouTube и Discord: например, example.com или полную ссылку. Эти адреса проверяются при подборе и сами попадают в список обхода. Не добавляйте сайты, которые и так открываются: обход им не поможет, а в редких случаях может помешать. Если сайт перестал открываться после добавления — уберите его из списка. У адресов роутера есть отметка «важный»: без такого сайта подбор на роутере считается неудачным.",
        [DomainLists] = "Ничего делать не нужно: списки обновляются сами, свои сайты — в «Свои адреса».\n\nОбход применяется не ко всему интернету, а только к сайтам из списков — так он не мешает остальному. Стандартные списки (YouTube, Discord и другие известные заблокированные сайты) приходят с обновлениями, править их нельзя. Свои сайты добавляйте в «Свои адреса». Исключения — сайты, которые обход не трогает, — есть у роутера: «На роутере» → «Списки роутера». Поддомены учитываются сами: строка example.com покрывает и video.example.com.",
        [IpLists] = "Включайте «Только из списков», если не работают игры или голосовые программы; сайтам это не нужно.\n\nНекоторые программы и игры не сообщают, к какому сайту идут, — только адрес (IP). Для них обход включается по списку адресов крупных сетей (Cloudflare, Google, игровые и хостинг-компании). «Только из списков» нужен для игр, голосовых программ и сайтов, которые замедляют целиком; для YouTube и Discord он не требуется. «Проверить, поможет ли обход» включает на 10 минут обход для любого соединения без проверки — только чтобы быстро понять, поможет ли он вообще: многие сайты в это время работают с ошибками, поэтому режим сам выключается. Список обновляется вместе с данными программы; свои подсети и исключения можно добавить ниже.",
        [Game] = "Включайте, только если игра не подключается к серверам или не работает голосовой чат в игре.\n\nИгры ходят не по «сайтовым» портам, а по случайным, поэтому обычный обход их не видит. Игровой режим включает обход на всех этих портах, но только к адресам из IP-списка, и подсовывает «приманку» в первые пакеты каждого соединения. Включайте, если игра не подключается к серверам или голосовой чат в игре не работает, а без обхода — тем более. Не включайте «на всякий случай»: растёт нагрузка на процессор (особенно при торрентах), может вырасти задержка (пинг), а некоторые программы (VPN, удалённый рабочий стол) могут начать сбоить. Если после включения что-то стало хуже — просто выключите.",
        [Hosts] = "Включайте, если не качаются файлы с GitHub, не открывается веб-версия Telegram или Discord запускается минутами.\n\nИногда провайдер блокирует не сайт, а конкретный адрес сервера — тогда ни обход, ни другой DNS не помогают, но у сайта есть другие адреса. Программа может записать такие адреса в системный файл hosts (список «сайт → адрес», который Windows смотрит раньше DNS) — только для GitHub, Telegram и Discord и только после проверки, что адрес действительно принадлежит этому сайту и отвечает. Записи помечены блоком «DpiShell», другие строки файла не меняются; копия файла сохраняется, «Вернуть как было» убирает только наши строки. Защитник Windows может предупредить об изменении hosts — это его реакция на любую правку этого файла. Устаревшие адреса программа проверяет раз в день и убирает сама.",
        [Dns] = "Меняйте DNS, если «Проверить DNS» нашёл подмену; в рабочей сети — не трогайте.\n\nDNS переводит имя сайта в адрес. Некоторые провайдеры подменяют ответы: сайт «не существует», хотя он есть; браузеры обходят это сами, а программы (Discord, игры) — нет. «Проверить DNS» сравнивает ответы вашего DNS с защищённым (DoH — запросы шифруются, провайдер их не видит и не подменяет). Если ответы подменяются, выберите защищённый DNS в «DNS этого компьютера» — программа сама поменяет его для Ethernet и Wi-Fi, а «Вернуть как было» вернёт прежний. Не включайте его, если компьютер в рабочей сети с внутренними адресами или вы пользуетесь фильтрами роутера: они перестанут действовать. DNS не чинит блокировку по адресу — для этого есть «Починить адреса».",
        [Diag] = "Заходите сюда, если обход включён, а сайты не открываются.\n\nЗдесь программа проверяет, что мешает обходу: другие программы обхода (их надо остановить), VPN, антивирусные и «игровые» сетевые службы, настройки прокси, подмену DNS, лишние строки в hosts. Зайдите сюда, если обход включён, а сайты не открываются, или перед тем, как писать о проблеме. Ничего не меняется без вашей кнопки: у каждой находки написано, что сделать. К вопросу о проблеме можно приложить журнал из «Папки логов».",
        [RouterMode] = "Оставьте «Все сайты»; «Только из списков» — если в нём ломается много сайтов.\n\n«Все сайты» — обход для любого сайта, кроме исключений: так открывается и то, что заблокировали недавно и чего ещё нет в списках. Если какой-то сайт после этого сломался, впишите его в «Сайт не открывается» — роутер проверит и предложит добавить в исключения. «Только из списков» — обход только для YouTube, Discord и сайтов из списков; выберите его, если в режиме «Все сайты» ломается много сайтов. После смены режима роутер сам перепроверит, что всё открывается.",
        [SiteCheck] = "Впишите сайт, который перестал открываться через роутер, — роутер скажет, мешает ли ему обход.\n\nВпишите адрес сайта, который не открывается, — роутер проверит его дважды: с обходом и без. Открывается только без обхода — значит, обход ему мешает: нажмите «Добавить в исключения», и роутер перестанет его трогать. Открывается с обходом — дело не в обходе: обновите страницу или попробуйте другой браузер. Не открывается и без обхода — сайт не работает сам или заблокирован по адресу.",
        [RouterDns] = "Включайте, если провайдер подменяет адреса сайтов; с родительским контролем провайдера — не нужно.\n\nРоутер раздаёт DNS всем устройствам дома: телефонам, телевизору, компьютерам. Если провайдер подменяет ответы, программы (Discord, игры) получают неверные адреса, и обход им не помогает. Защищённый DNS — роутер будет узнавать адреса через зашифрованные серверы (DoH), провайдер их не подменит. Не включайте, если пользуетесь фильтрами провайдера (родительский контроль): они перестанут действовать. Прежние настройки сохраняются, «Вернуть как было» возвращает их.",
        [RouterWatchdog] = "Оставьте включённым: если обход на роутере сломает интернет, роутер выключит его сам.\n\nСторож раз в несколько минут проверяет, открываются ли сайты. Пропал интернет с обходом, а без обхода есть — роутер выключает обход и пишет об этом здесь и на главной; включить снова можно одной кнопкой. Выключайте сторожа, только если он срабатывает зря. Выключить обход можно и без программы: короткое нажатие (1–4 с) кнопки reset на корпусе роутера — выключить обход без перезагрузки.",
    };

    public static string Get(string? topic) => topic is not null && All.TryGetValue(topic, out var t) ? t : "";
}
